// Types describe the shape of data; tsc checks them before the code runs.
type Priority = "low" | "normal" | "urgent";            // a union of exact strings

interface Ticket {
  id: number;
  subject: string;
  priority: Priority;
  assignee?: string;                                     // optional: may be missing
}

type Result =
  | { ok: true; ticket: Ticket }
  | { ok: false; error: string };                        // a discriminated union

function parsePriority(text: string): Priority {
  const p = text.trim().toLowerCase();
  if (p === "low" || p === "normal" || p === "urgent") return p;   // narrowed to Priority
  return "normal";
}

function makeTicket(id: number, subject: string, prio: string): Result {
  if (subject.length === 0) return { ok: false, error: "subject is empty" };
  return { ok: true, ticket: { id, subject, priority: parsePriority(prio) } };
}

for (const r of [makeTicket(1, "Refund not received", " URGENT "), makeTicket(2, "", "low")]) {
  if (r.ok) {                                            // TypeScript now knows r.ticket exists
    const who = r.ticket.assignee ?? "unassigned";       // handle the missing case
    console.log(r.ticket.id, r.ticket.priority, who);
  } else {
    console.log("rejected:", r.error);
  }
}
// Output (node src/types.ts):
// 1 urgent unassigned
// rejected: subject is empty

type Order = { id: number; total: number };

// A fake API call: answers after `ms` milliseconds, fails for id 3.
function fetchOrder(id: number, ms: number): Promise<Order> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id === 3) reject(new Error(`order ${id} not found`));
      else resolve({ id, total: id * 10 });
    }, ms);
  });
}

const roughMs = (start: number) => Math.round((Date.now() - start) / 100) * 100;

async function main(): Promise<void> {
  let t = Date.now();
  const a = await fetchOrder(1, 300);                     // one after the other
  const b = await fetchOrder(2, 300);
  console.log("sequential:", a.total + b.total, "in about", roughMs(t), "ms");

  t = Date.now();
  const both = await Promise.all([fetchOrder(1, 300), fetchOrder(2, 300)]);   // at the same time
  console.log("parallel:", both.map((o) => o.total), "in about", roughMs(t), "ms");

  try {
    await fetchOrder(3, 100);
  } catch (err) {
    console.log("caught:", (err as Error).message);
  }

  const settled = await Promise.allSettled([1, 3].map((id) => fetchOrder(id, 100)));
  console.log("allSettled:", settled.map((r) => r.status));
}

main().catch((err) => { console.error(err); process.exit(1); });
// Output:
// sequential: 30 in about 600 ms
// parallel: [ 10, 20 ] in about 300 ms
// caught: order 3 not found
// allSettled: [ 'fulfilled', 'rejected' ]

import { z } from "zod";

const Lead = z.object({
  company: z.string().min(1),
  email: z.email(),                                   // zod 3 wrote z.string().email()
  seats: z.coerce.number().int().positive(),          // "12" from a form becomes 12
  plan: z.enum(["starter", "team", "enterprise"]).default("starter"),
});
type Lead = z.infer<typeof Lead>;                     // the TypeScript type, for free

const inputs: unknown[] = [                           // unknown: we trust nothing yet
  { company: "Quillon Bakery", email: "ops@quillon.example", seats: "12" },
  { company: "", email: "not-an-email", seats: -3, plan: "gold" },
];

for (const input of inputs) {
  const r = Lead.safeParse(input);                    // never throws; check r.success
  if (r.success) {
    const lead: Lead = r.data;
    console.log("ok:", JSON.stringify(lead));
  } else {
    for (const issue of r.error.issues) {
      console.log("bad:", issue.path.join("."), "-", issue.message);
    }
  }
}
// Output:
// ok: {"company":"Quillon Bakery","email":"ops@quillon.example","seats":12,"plan":"starter"}
// bad: company - Too small: expected string to have >=1 characters
// bad: email - Invalid email address
// bad: seats - Too small: expected number to be >0
// bad: plan - Invalid option: expected one of "starter"|"team"|"enterprise"

import { createServer } from "node:http";
import Anthropic from "@anthropic-ai/sdk";
import { z } from "zod";

const MODEL = process.env.MODEL ?? "MODEL";          // put a current model id in the environment
const client = new Anthropic();                      // reads ANTHROPIC_API_KEY from the environment
const Body = z.object({ ticket: z.string().min(10).max(5000) });

async function summarise(ticket: string): Promise<string> {
  const msg = await client.messages.create({
    model: MODEL,
    max_tokens: 300,
    system: "Summarise the customer's support ticket in one sentence for a support agent.",
    messages: [{ role: "user", content: ticket }],
  });
  // A reply is a list of content blocks; join the text ones.
  return msg.content.filter((b) => b.type === "text").map((b) => b.text).join("");
}

createServer(async (req, res) => {
  if (req.method !== "POST" || req.url !== "/summarise") {
    res.writeHead(404).end();
    return;
  }
  let raw = "";
  for await (const chunk of req) raw += chunk;
  let json: unknown = null;
  try { json = JSON.parse(raw); } catch { /* leave json as null */ }

  const parsed = Body.safeParse(json);               // validate before spending tokens
  if (!parsed.success) {
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: parsed.error.issues.map((i) => `${i.path.join(".")}: ${i.message}`) }));
    return;
  }
  try {
    const summary = await summarise(parsed.data.ticket);
    res.writeHead(200, { "Content-Type": "application/json" }).end(JSON.stringify({ summary }));
  } catch (err) {
    console.error("model call failed:", err);        // full detail in the server log only
    res.writeHead(502, { "Content-Type": "application/json" }).end(JSON.stringify({ error: "model call failed" }));
  }
}).listen(3000, () => console.log("listening on http://localhost:3000"));

// Try it (bad input is rejected before any model call):
// $ curl -s -X POST localhost:3000/summarise -d '{"ticket":"short"}'
// {"error":["ticket: Too small: expected string to have >=10 characters"]}

