// Turns "£1,250.50", "1250" or " 12.5 " into a number; returns null when it cannot.
export function parseAmount(text: string): number | null {
  const cleaned = text.trim().replace(/^[£$€]/, "").replaceAll(",", "");
  if (cleaned === "" || !/^-?\d+(\.\d+)?$/.test(cleaned)) return null;
  return Math.round(Number(cleaned) * 100) / 100;     // money: keep two decimals
}

